+import * as ethers from 'ethers';
+
+type BigNumberInput = bigint | number | string | { toBigInt(): bigint };
+
+const toHex = (value: bigint) => {
+  const sign = value < 0n ? '-' : '';
+  let hex = (value < 0n ? -value : value).toString(16);
+  if (hex.length % 2) hex = `0${hex}`;
+  return `${sign}0x${hex}`;
+};
+
+export class BigNumber {
+  readonly hex: string;
+
+  readonly type = 'BigNumber';
+
+  private readonly value: bigint;
+
+  private constructor(value: bigint) {
+    this.value = value;
+    this.hex = toHex(value);
+  }
+
+  static from(value: BigNumberInput): BigNumber {
+    if (value instanceof BigNumber) return value;
+    if (typeof value === 'object') return new BigNumber(value.toBigInt());
+    return new BigNumber(BigInt(value));
+  }
+
+  gte(value: BigNumberInput): boolean {
+    return this.value >= BigNumber.from(value).value;
+  }
+
+  sub(value: BigNumberInput): BigNumber {
+    return new BigNumber(this.value - BigNumber.from(value).value);
+  }
+
+  toBigInt(): bigint {
+    return this.value;
+  }
+
+  toHexString(): string {
+    return this.hex;
+  }
+
+  toString(): string {
+    return this.value.toString();
+  }
+}
+
+const mutableEthers = ethers as typeof ethers & { BigNumber?: typeof BigNumber };
+
+if (!mutableEthers.BigNumber) {
+  Object.defineProperty(mutableEthers, 'BigNumber', {
+    configurable: true,
+    enumerable: true,
+    value: BigNumber,
+  });
+}
+
+export const toBigInt = (value: BigNumberInput): bigint =>
+  typeof value === 'bigint' ? value : BigNumber.from(value).toBigInt();
